import { SignalingClient } from '@/signaling/SignalingClient'
import { WebRtcClient } from '@/webrtc/WebRtcClient'
import type { IceCandidatePayload, JoinPayload } from '@/signaling/types'

export interface ServerVoiceConnectionOptions {
  url: string
  token: string
  roomId: string
  displayName: string
  onState?: (state: RTCPeerConnectionState) => void
  onStream?: (stream: MediaStream) => void
}

/** Owns exactly one browser ↔ plugin WebRTC session. */
export class ServerVoiceConnection {
  private readonly signaling: SignalingClient
  private readonly rtc: WebRtcClient
  private readonly options: ServerVoiceConnectionOptions
  private peerId: string | null = null
  private remoteAudio: HTMLAudioElement | null = null

  constructor(options: ServerVoiceConnectionOptions) {
    this.options = options
    this.signaling = new SignalingClient({ url: options.url })
    this.rtc = new WebRtcClient({
      onIceCandidate: candidate => this.sendIceCandidate(candidate),
      onConnectionStateChange: state => options.onState?.(state as RTCPeerConnectionState),
      onTrack: (_track, stream) => this.playRemoteStream(stream),
    })
    this.bindSignaling()
  }

  async connect(): Promise<MediaStream | null> {
    await this.rtc.initialize()
    await this.signaling.connect()
    await this.signaling.join({
      token: this.options.token,
      roomId: this.options.roomId,
      displayName: this.options.displayName,
    })
    return this.rtc.getLocalStream()
  }

  disconnect(): void {
    this.signaling.disconnect()
    this.rtc.close()
    this.remoteAudio?.remove()
    this.remoteAudio = null
    this.peerId = null
  }

  setMuted(muted: boolean): void {
    this.rtc.setMuted(muted)
  }

  private bindSignaling(): void {
    this.signaling.addEventListener('joined', (event: Event) => {
      const { peerId } = (event as CustomEvent<{ peerId: string }>).detail
      this.peerId = peerId
      void this.sendOffer()
    })
    this.signaling.addEventListener('answer', (event: Event) => {
      const { sdp } = (event as CustomEvent<{ sdp: string }>).detail
      void this.rtc.setRemoteDescription({ type: 'answer', sdp })
    })
    this.signaling.addEventListener('icecandidate', (event: Event) => {
      const payload = (event as CustomEvent<IceCandidatePayload>).detail
      void this.rtc.addIceCandidate({
        candidate: payload.candidate,
        sdpMid: payload.sdpMid,
        sdpMLineIndex: payload.sdpMLineIndex,
      })
    })
  }

  private async sendOffer(): Promise<void> {
    if (!this.peerId) return
    const offer = await this.rtc.createOffer()
    await this.signaling.sendOffer({
      roomId: this.options.roomId,
      to: this.peerId,
      sdp: offer.sdp ?? '',
    })
  }

  private async sendIceCandidate(candidate: RTCIceCandidateInit): Promise<void> {
    if (!this.peerId || !candidate.candidate) return
    await this.signaling.sendIceCandidate({
      roomId: this.options.roomId,
      to: this.peerId,
      candidate: candidate.candidate,
      sdpMid: candidate.sdpMid ?? '',
      sdpMLineIndex: candidate.sdpMLineIndex ?? 0,
    })
  }

  private playRemoteStream(stream: MediaStream): void {
    if (!this.remoteAudio) {
      this.remoteAudio = document.createElement('audio')
      this.remoteAudio.autoplay = true
      this.remoteAudio.setAttribute('aria-hidden', 'true')
      document.body.append(this.remoteAudio)
    }
    this.remoteAudio.srcObject = stream
    void this.remoteAudio.play().catch(() => undefined)
    this.options.onStream?.(stream)
  }
}
